/// <summary>
/// One row of HSMobileOpsPostQueue, as the Activity screen needs it - what was submitted, what
/// it is now, and why.
///
/// linesJson and userName were deliberately left off at first - "a status list has no use for
/// them." Confirmed wrong: a status list with only a PO number and a status word gives a
/// supervisor no way to tell what actually happened without opening D365FO separately. Both are
/// columns already on the row, so exposing them costs nothing extra to read - the client parses
/// linesJson itself (the same shape it sent), so nothing here needs to resolve item names.
/// </summary>
[DataContractAttribute]
class HSMobileOpsPostQueueEntry
{
    str         sourceId;
    str         documentType;
    str         status;
    str         errorMessage;
    utcdatetime receivedUtc;
    utcdatetime processedUtc;
    str         userName;
    str         linesJson;
    str         idempotencyKey;
    str         grnId;
    int         lineCount;

}

Method.Source:
[DataMemberAttribute('SourceId')]
public str parmSourceId(str _value = sourceId)
{
    sourceId = _value;
    return sourceId;
}

[DataMemberAttribute('DocumentType')]
public str parmDocumentType(str _value = documentType)
{
    documentType = _value;
    return documentType;
}

[DataMemberAttribute('Status')]
public str parmStatus(str _value = status)
{
    status = _value;
    return status;
}

[DataMemberAttribute('ErrorMessage')]
public str parmErrorMessage(str _value = errorMessage)
{
    errorMessage = _value;
    return errorMessage;
}

[DataMemberAttribute('ReceivedUtc')]
public utcdatetime parmReceivedUtc(utcdatetime _value = receivedUtc)
{
    receivedUtc = _value;
    return receivedUtc;
}

[DataMemberAttribute('ProcessedUtc')]
public utcdatetime parmProcessedUtc(utcdatetime _value = processedUtc)
{
    processedUtc = _value;
    return processedUtc;
}

[DataMemberAttribute('UserName')]
public str parmUserName(str _value = userName)
{
    userName = _value;
    return userName;
}

/// <summary>
/// Exactly what the device sent - LineNumber, ItemId, Quantity and the capture dimensions per
/// line. The client already owns a parser for this shape (it built the request), so nothing
/// here re-parses it just to flatten it into a display string the client would have to
/// re-derive its own formatting from anyway.
/// </summary>
[DataMemberAttribute('LinesJson')]
public str parmLinesJson(str _value = linesJson)
{
    linesJson = _value;
    return linesJson;
}

[DataMemberAttribute('IdempotencyKey')]
public str parmIdempotencyKey(str _value = idempotencyKey)
{
    idempotencyKey = _value;
    return idempotencyKey;
}

/// <summary>The product receipt posted with this registration, when Auto GRN is on.</summary>
[DataMemberAttribute('GrnId')]
public str parmGrnId(str _value = grnId)
{
    grnId = _value;
    return grnId;
}

[DataMemberAttribute('LineCount')]
public int parmLineCount(int _value = lineCount)
{
    lineCount = _value;
    return lineCount;
}
